-- v5.0.0 source IP policy. Generated by tools/v500_generate_network_access.py.

-- Default disabled; revision/rules and their audit are committed atomically by platform services.

CREATE TABLE IF NOT EXISTS CX_IP_ACCESS_REVISIONS (REVISION INTEGER PRIMARY KEY CHECK(REVISION>0), ENABLED VARCHAR(1) NOT NULL CHECK(ENABLED IN ('Y','N')), LIST_MODE VARCHAR(16) NOT NULL CHECK(LIST_MODE IN ('ALLOWLIST','DENYLIST')), UPDATED_BY VARCHAR(128) NOT NULL, REASON VARCHAR(2000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);

CREATE TABLE IF NOT EXISTS CX_IP_ACCESS_STATE (POLICY_KEY VARCHAR(16) PRIMARY KEY CHECK(POLICY_KEY='GLOBAL'), REVISION INTEGER NOT NULL REFERENCES CX_IP_ACCESS_REVISIONS(REVISION));

CREATE TABLE IF NOT EXISTS CX_IP_ACCESS_RULES (REVISION INTEGER NOT NULL REFERENCES CX_IP_ACCESS_REVISIONS(REVISION), RULE_NO INTEGER NOT NULL CHECK(RULE_NO>=1 AND RULE_NO<=512), NETWORK_CIDR VARCHAR(64) NOT NULL, IP_VERSION INTEGER NOT NULL CHECK(IP_VERSION IN (4,6)), PRIMARY KEY(REVISION,RULE_NO), UNIQUE(REVISION,NETWORK_CIDR));

INSERT INTO CX_IP_ACCESS_REVISIONS(REVISION,ENABLED,LIST_MODE,UPDATED_BY,REASON) SELECT 1,'N','DENYLIST','SYSTEM_BOOTSTRAP','Initial disabled source IP policy' WHERE NOT EXISTS (SELECT 1 FROM CX_IP_ACCESS_REVISIONS WHERE REVISION=1);

INSERT INTO CX_IP_ACCESS_STATE(POLICY_KEY,REVISION) SELECT 'GLOBAL',1 WHERE NOT EXISTS (SELECT 1 FROM CX_IP_ACCESS_STATE WHERE POLICY_KEY='GLOBAL');

CREATE OR REPLACE FUNCTION cx102_reject_ip_policy_mutation() RETURNS trigger LANGUAGE plpgsql AS $cx102$ BEGIN RAISE EXCEPTION 'IP policy history is immutable' USING ERRCODE='23000'; END $cx102$;

REVOKE ALL ON FUNCTION cx102_reject_ip_policy_mutation() FROM PUBLIC;

CREATE OR REPLACE TRIGGER CX102_REVISIONS BEFORE DELETE OR UPDATE OF REVISION,ENABLED,LIST_MODE,UPDATED_BY,REASON,CREATED_AT ON CX_IP_ACCESS_REVISIONS FOR EACH STATEMENT EXECUTE FUNCTION cx102_reject_ip_policy_mutation();

REVOKE ALL ON CX_IP_ACCESS_REVISIONS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX102_STATE BEFORE DELETE OR UPDATE OF POLICY_KEY ON CX_IP_ACCESS_STATE FOR EACH STATEMENT EXECUTE FUNCTION cx102_reject_ip_policy_mutation();

REVOKE ALL ON CX_IP_ACCESS_STATE FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX102_RULES BEFORE DELETE OR UPDATE OF REVISION,RULE_NO,NETWORK_CIDR,IP_VERSION ON CX_IP_ACCESS_RULES FOR EACH STATEMENT EXECUTE FUNCTION cx102_reject_ip_policy_mutation();

REVOKE ALL ON CX_IP_ACCESS_RULES FROM PUBLIC, ai_agent_runtime;
